const c=window.STORE_CONFIG||{};let sb;const $=x=>document.getElementById(x),money=n=>`₦${Number(n||0).toLocaleString()}`;
async function login(){sb=sb||supabase.createClient(c.supabaseUrl,c.supabaseAnonKey);const {error}=await sb.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(error)return $('msg').textContent=error.message;await loadAll()}
async function api(action,payload={}){const {data:{session}}=await sb.auth.getSession();const r=await fetch(`${c.supabaseUrl}/functions/v1/admin-api`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,apikey:c.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({action,payload})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function loadAll(){try{$('panel').classList.remove('hidden');const [d,f,t]=await Promise.all([api('dashboard'),api('funding'),api('transactions')]);$('users').textContent=d.users;$('pending').textContent=d.pending_funding;$('txs').textContent=d.transactions;$('funds').innerHTML=f.map(x=>`<div class="listitem"><div><b>${money(x.amount)} · ${x.profiles?.full_name||'Customer'}</b><small>${x.payment_reference||'No reference'} · ${x.status}</small></div>${x.status==='pending'?`<div><button onclick="review('${x.id}','approved')">Approve</button> <button onclick="review('${x.id}','rejected')">Reject</button></div>`:''}</div>`).join('')||'No funding requests';$('adminTx').innerHTML=t.map(x=>`<div class="listitem"><div><b>${x.description||x.type}</b><small>${x.phone||''}</small></div><div><b>${money(x.amount)}</b><small>${x.status}</small></div></div>`).join('')||'No transactions'}catch(e){$('msg').textContent=e.message}}
async function review(id,status){if(!confirm(`${status} this funding request?`))return;try{await api('review_funding',{id,status});await loadAll()}catch(e){alert(e.message)}}
(async()=>{if(!c.supabaseUrl||!c.supabaseAnonKey)return;$('msg').textContent='';sb=supabase.createClient(c.supabaseUrl,c.supabaseAnonKey);const {data:{session}}=await sb.auth.getSession();if(session)await loadAll()})();
